)  AS Source ([SyncTableToScopeMapGuid], [ID], [SyncScopeGuid], [SyncTableGuid], 
	[SyncOrder], [SyncDirection], [MaxBatchSegmentRowCount], [MaxTransferSegmentKB], [AdditionalFilterJoinClause], 
	[AdditionalFilterWhereClause], [CreatedDate], [CreatedBy], [UpdatedDate], [UpdatedBy], [ClientTableNameOverride], [FirstTimeSyncOption])
ON (Target.[SyncTableToScopeMapGuid] = Source.[SyncTableToScopeMapGuid])
WHEN MATCHED AND (Target.[ID] <> Source.[ID] 
					OR Target.[SyncScopeGuid] <> Source.[SyncScopeGuid]
					OR Target.[SyncTableGuid] <> Source.[SyncTableGuid]
					OR Target.[SyncOrder] <> Source.[SyncOrder]
					OR Target.[SyncDirection] <> Source.[SyncDirection]
					OR Target.[MaxBatchSegmentRowCount] <> Source.[MaxBatchSegmentRowCount]
					OR Target.[MaxTransferSegmentKB] <> Source.[MaxTransferSegmentKB]
					OR Target.[AdditionalFilterJoinClause] <> Source.[AdditionalFilterJoinClause]
					OR Target.[AdditionalFilterWhereClause] <> Source.[AdditionalFilterWhereClause]
					OR Target.[ClientTableNameOverride] <> Source.[ClientTableNameOverride]
					OR Target.[FirstTimeSyncOption] <> Source.[FirstTimeSyncOption]) THEN
	UPDATE SET 
				  [ID] = Source.[ID]
				, [SyncScopeGuid] = Source.[SyncScopeGuid]
				, [SyncTableGuid] = Source.[SyncTableGuid]
				, [SyncOrder] = Source.[SyncOrder]
				, [SyncDirection] = Source.[SyncDirection]
				, [MaxBatchSegmentRowCount] = Source.[MaxBatchSegmentRowCount]
				, [MaxTransferSegmentKB] = Source.[MaxTransferSegmentKB]
				, [AdditionalFilterJoinClause] = Source.[AdditionalFilterJoinClause]
				, [AdditionalFilterWhereClause] = Source.[AdditionalFilterWhereClause]
				, [CreatedDate] = Source.[CreatedDate]
				, [CreatedBy] =	Source.[CreatedBy]
				, [UpdatedDate] = Source.[UpdatedDate]
				, [UpdatedBy] =	Source.[UpdatedBy]
				, [ClientTableNameOverride] =	Source.[ClientTableNameOverride]
				, [FirstTimeSyncOption] = Source.[FirstTimeSyncOption]
WHEN NOT MATCHED THEN
	INSERT ([SyncTableToScopeMapGuid], [ID], [SyncScopeGuid], [SyncTableGuid], 
	[SyncOrder], [SyncDirection], [MaxBatchSegmentRowCount], [MaxTransferSegmentKB], [AdditionalFilterJoinClause], 
	[AdditionalFilterWhereClause], [CreatedDate], [CreatedBy], [UpdatedDate], [UpdatedBy], [ClientTableNameOverride], [FirstTimeSyncOption])
		VALUES (Source.[SyncTableToScopeMapGuid], Source.[ID], Source.[SyncScopeGuid], Source.[SyncTableGuid],
		Source.[SyncOrder], Source.[SyncDirection], Source.[MaxBatchSegmentRowCount], Source.[MaxTransferSegmentKB], Source.[AdditionalFilterJoinClause],
		Source.[AdditionalFilterWhereClause], Source.[CreatedDate],Source.[CreatedBy],Source.[UpdatedDate],Source.[UpdatedBy], Source.[ClientTableNameOverride], Source.[FirstTimeSyncOption])
OUTPUT
	$action AS ActionType,
	deleted.[SyncTableToScopeMapGuid], 
	inserted.[SyncTableToScopeMapGuid], 
	deleted.[ID], 
	inserted.[ID], 
	deleted.[SyncScopeGuid],
	inserted.[SyncScopeGuid],
	deleted.[SyncTableGuid], 
	inserted.[SyncTableGuid], 
	deleted.[SyncOrder], 
	inserted.[SyncOrder], 
	deleted.[SyncDirection], 
	inserted.[SyncDirection], 
	deleted.[MaxBatchSegmentRowCount], 
	inserted.[MaxBatchSegmentRowCount], 
	deleted.[MaxTransferSegmentKB], 
	inserted.[MaxTransferSegmentKB], 
	deleted.[AdditionalFilterJoinClause],
	inserted.[AdditionalFilterJoinClause],
	deleted.[AdditionalFilterWhereClause], 
	inserted.[AdditionalFilterWhereClause], 
	deleted.[ClientTableNameOverride], 
	inserted.[ClientTableNameOverride], 
	deleted.[CreatedDate],
	inserted.[CreatedDate],
	deleted.[CreatedBy],
	inserted.[CreatedBy],
	deleted.[UpdatedDate],
	inserted.[UpdatedDate],
	deleted.[UpdatedBy],
	inserted.[UpdatedBy],
	deleted.[_ClusterIdx],
	inserted.[_ClusterIdx],
	deleted.[FirstTimeSyncOption],
	inserted.[FirstTimeSyncOption]
INTO @tblSyncTableToScopeMapData;

SELECT @SyncTableToScopeMapDataInserted = COUNT(*) FROM @tblSyncTableToScopeMapData WHERE ActionType IN ( 'INSERT' );
SELECT @SyncTableToScopeMapDataUpdated = COUNT(*) FROM @tblSyncTableToScopeMapData WHERE ActionType IN ( 'UPDATE' )
SELECT @SyncTableToScopeMapDataDeleted = COUNT(*) FROM @tblSyncTableToScopeMapData WHERE ActionType IN ( 'DELETE' )

IF (@SyncTableToScopeMapDataInserted > 0)
BEGIN
	PRINT '** ' + CONVERT(NVARCHAR(25), @SyncTableToScopeMapDataInserted) + ' NEW RECORDS INSERTED INTO [sync].[tblSyncTableToScopeMap] **'
	PRINT ''
END

IF (@SyncTableToScopeMapDataUpdated > 0)
BEGIN
	PRINT '** ' + CONVERT(NVARCHAR(25), @SyncTableToScopeMapDataUpdated) + ' EXISTING RECORDS UPDATED IN [sync].[tblSyncTableToScopeMap] **'
	PRINT ''
	SELECT * FROM @tblSyncTableToScopeMapData WHERE ActionType IN ( 'UPDATE' );
END

SET NOCOUNT OFF